      description: 'Run a task that reports monotonic progress from 0 to 1.',
      inputSchema: {
        type: 'object',
        properties: {
          steps: {
            type: 'integer',
            description: 'The number of progress steps (positive integer).',
            minimum: 1,
          },
        },
        required: ['steps'],
        additionalProperties: false,
      },
    },
  ];
