{"command": "node -e "
import('./server.mjs').then(async ({callTool}) => {
  // invalid steps
  try { await callTool('run_with_progress', {steps: 0}); console.log('FAIL: no error for steps=0'); }
  catch(e) { console.log('OK invalid steps=0:', e.message, 'code:', e.code); }
  try { await callTool('run_with_progress', {steps: -3}); console.log('FAIL: no error for steps=-3'); }
  catch(e) { console.log('OK invalid steps=-3:', e.message, 'code:', e.code); }
  try { await callTool('run_with_progress', {steps: 2.5}); console.log('FAIL: no error for steps=2.5'); }
  catch(e) { console.log('OK invalid steps=2.5:', e.message, 'code:', e.code); }
  // unknown tool
  try { await callTool('does_not_exist', {}); console.log('FAIL: no error for unknown tool'); }
  catch(e) { console.log('OK unknown tool:', e.message, 'code:', e.code); }
  // no callback provided (should still work and return completed)
  const r = await callTool('run_with_progress', {steps: 3});
  console.log('OK no-callback result:', JSON.stringify(r));
  // steps=1 progress values
  const v=[]; await callTool('run_with_progress', {steps:1}, {onProgress:x=>v.push(x)});
  console.log('OK steps=1 progress:', JSON.stringify(v));
});
""}

